//! Parity between the Rust log-mel front end and the reference implementation.
//!
//! This is the highest-value test in the repository. The front end is a
//! hand-written port of a NeMo pipeline with several non-obvious conventions
//! (Bessel correction, a symmetric window, `log_zero_guard_value == 2^-24`,
//! exactly one extra STFT frame). A mistake in any of them produces
//! *plausible* transcripts that are quietly worse, which is the worst class of
//! bug this product can have.
//!
//! The fixture is generated by `scripts/make_golden.py`, which computes the
//! features with the model's own `extract_features` and cross-checks an
//! independent transcription of the same maths. It contains a deterministic
//! synthetic signal and no user audio.
//!
//! The tolerance is 2e-4 on values that are O(1) after normalisation. That is
//! roughly float32 epsilon accumulated over a 512-point FFT, a 128-term dot
//! product, and a per-band mean and variance. It is loose enough to absorb
//! different-but-equivalent summation orders between torch's kernels and
//! `rustfft`, and tight enough that every convention error found while writing
//! this -- a left-aligned instead of centred window, a missing Bessel
//! correction -- misses it by three to four orders of magnitude.

use std::path::PathBuf;

use vaani_asr::frontend::{FrontendParams, FrontendTables, log_mel};

fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(|p| p.parent())
        .expect("crate is under <root>/crates/vaani-asr")
        .to_path_buf()
}

fn fixture() -> Option<PathBuf> {
    let p = repo_root()
        .join("tests")
        .join("fixtures")
        .join("sravaani")
        .join("frontend_golden.json");
    p.is_file().then_some(p)
}

fn artefacts_dir() -> Option<PathBuf> {
    let p = vaani_asr::default_dir();
    p.join("preproc.json").is_file().then_some(p)
}

#[derive(serde::Deserialize)]
struct Golden {
    sample_rate: u32,
    n_samples: usize,
    signal: Vec<f32>,
    n_mels: usize,
    n_frames: usize,
    valid_frames: usize,
    log_mel: Vec<Vec<f64>>,
}

#[test]
fn log_mel_matches_the_reference_to_1e4() {
    let (Some(fx), Some(dir)) = (fixture(), artefacts_dir()) else {
        println!(
            "skipping: need both tests/fixtures/sravaani/frontend_golden.json and \
             artifacts/sravaani/. Run:\n  python scripts\\make_golden.py --src SraVaani-1.0 --out tests\\fixtures\n  \
             python scripts\\export_sravaani_onnx.py --src SraVaani-1.0 --out artifacts\\sravaani"
        );
        return;
    };

    let text = std::fs::read_to_string(&fx).expect("fixture must be readable");
    let g: Golden = serde_json::from_str(&text).expect("fixture must parse");

    let params = FrontendParams::load(&dir).expect("preproc must load");
    let tables = FrontendTables::load(&dir, &params).expect("tables must load");
    let got = log_mel(&g.signal, &params, &tables).expect("log_mel must succeed");

    assert_eq!(params.sample_rate, g.sample_rate);
    // The fixture records the signal length it used; confirming we read the
    // same array guards against a truncated JSON fixture silently making this
    // test easier to pass.
    assert_eq!(
        g.signal.len(),
        g.n_samples,
        "fixture is internally inconsistent"
    );
    assert_eq!(g.log_mel.len(), g.n_mels);
    assert_eq!(g.log_mel[0].len(), g.n_frames);
    assert_eq!(got.n_mels, g.n_mels, "mel band count");
    assert_eq!(got.n_frames, g.n_frames, "STFT frame count");
    assert_eq!(got.valid_frames, g.valid_frames, "feature_lengths");
    assert_eq!(got.data.len(), g.n_mels * g.n_frames);

    let mut worst = 0f64;
    let mut worst_at = (0usize, 0usize);
    for (m, row) in g.log_mel.iter().enumerate() {
        for (f, expected) in row.iter().enumerate() {
            let actual = f64::from(got.at(m, f));
            let d = (actual - expected).abs();
            if d > worst {
                worst = d;
                worst_at = (m, f);
            }
        }
    }
    println!(
        "log-mel parity: {n}x{f} cells, max |rust - reference| = {worst:.3e} at mel {m} frame {fr}",
        n = g.n_mels,
        f = g.n_frames,
        m = worst_at.0,
        fr = worst_at.1
    );
    assert!(
        worst <= 2e-4,
        "log-mel differs from the reference by {worst:.3e} at mel {} frame {}: \
         a convention in the front end is wrong (see the module docs on Bessel \
         correction, the symmetric window, and log_zero_guard_value)",
        worst_at.0,
        worst_at.1
    );
}

#[test]
fn every_cell_is_finite() {
    let (Some(fx), Some(dir)) = (fixture(), artefacts_dir()) else {
        println!("skipping: fixtures or artefacts absent");
        return;
    };
    let g: Golden = serde_json::from_str(&std::fs::read_to_string(&fx).unwrap()).unwrap();
    let params = FrontendParams::load(&dir).unwrap();
    let tables = FrontendTables::load(&dir, &params).unwrap();
    let got = log_mel(&g.signal, &params, &tables).unwrap();
    assert!(
        got.data.iter().all(|v| v.is_finite()),
        "a NaN or Inf would propagate through the encoder and produce a \
         transcript of garbage that still looks like language"
    );
}

#[test]
fn padding_frames_match_the_reference() {
    // The fixture's padding frames must come out at exactly pad_value, not
    // merely "close to it": the encoder's attention masks on feature_lengths,
    // and a non-zero pad leaks the final frame into the pooled output.
    let (Some(fx), Some(dir)) = (fixture(), artefacts_dir()) else {
        println!("skipping: fixtures or artefacts absent");
        return;
    };
    let g: Golden = serde_json::from_str(&std::fs::read_to_string(&fx).unwrap()).unwrap();
    let params = FrontendParams::load(&dir).unwrap();
    let tables = FrontendTables::load(&dir, &params).unwrap();
    let got = log_mel(&g.signal, &params, &tables).unwrap();
    for m in 0..g.n_mels {
        for f in g.valid_frames..g.n_frames {
            assert_eq!(got.at(m, f), 0.0, "mel {m} frame {f} should be pad_value");
        }
    }
}
